use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200000
    let mut comp = []
    for i in 0..(limit + 1) { comp.push(false) }
    let mut counts = []
    let mut largest = []
    let mut c = 0
    let mut last = 0
    for i in 0..(limit + 1) {
        if i >= 2 && !comp[i] {
            c += 1
            last = i
            if i <= 500 {
                let mut j = i * i
                while j <= limit {
                    comp[j] = true
                    j += i
                }
            }
        }
        counts.push(c)
        largest.push(last)
    }
    let mut first = true
    let mut out = ""
    for line in text.lines() {
        let s = line.trim()
        if s.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = s.parse().unwrap_or(0)
        if counts[n] == 0 {
            out = out + "0 none\n"
        } else {
            out = out + "${counts[n]} ${largest[n]}\n"
        }
    }
    print(out)
}

